package dev.vladeezyy.iceandfire.bus;

/** The client-only @SubscribeEvent methods (generated by tools/port_events.py) */
public final class ClientEventIndex {
    private ClientEventIndex() {
    }

    public static void register() {
        com.github.alexthe666.iceandfire.event.ClientEvents clientEvents = new com.github.alexthe666.iceandfire.event.ClientEvents();
        com.github.alexthe666.iceandfire.event.PlayerRenderEvents playerRenderEvents = new com.github.alexthe666.iceandfire.event.PlayerRenderEvents();
        IafBus.add(EntityMountEvent.class, EventPriority.NORMAL, clientEvents::onEntityMount);
        IafBus.add(EntityTickEvent.Pre.class, EventPriority.NORMAL, clientEvents::onLivingUpdate);
        IafBus.add(FMLClientSetupEvent.class, EventPriority.NORMAL, com.github.alexthe666.iceandfire.client.IafClientSetup::setupClient);
        IafBus.add(RenderLivingEvent.Post.class, EventPriority.NORMAL, clientEvents::onPostRenderLiving);
        IafBus.add(RenderLivingEvent.Pre.class, EventPriority.NORMAL, clientEvents::onPreRenderLiving);
        IafBus.add(RenderPlayerEvent.Pre.class, EventPriority.NORMAL, playerRenderEvents::playerRender);
        IafBus.add(ScreenEvent.Opening.class, EventPriority.NORMAL, clientEvents::onGuiOpened);
        IafBus.add(ViewportEvent.ComputeCameraAngles.class, EventPriority.NORMAL, clientEvents::onCameraSetup);
    }
}
